<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Accessor\SmtpOutboundConfigUseTlsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigUseTlsAccessor trait.
 *
 * Covers null default, string/VO assignment via withUseTls,
 * getUseTls/useTls accessors, and isUseTlsChanged with/without original.
 */
class SmtpOutboundConfigUseTlsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUseTls creates a new instance with the UseTls set
     * from a string value, and getUseTls returns the primitive string.
     */
    public function testWithUseTlsFromString(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigUseTlsAccessorUnitTest();

        // Act
        $result = $holder->withUseTls(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isUseTls());
    }
    /**
     * Asserts that withuseTls has access to the value object
     * from a string value, and getUseTls returns the primitive string.
     */
    public function testWithUseTlsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigUseTlsAccessorUnitTest();

        // Act
        $result = $holder->withUseTls(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->useTls()->value());
    }
    public function testChangedUseTls(): void
    {
        // Arrange
        $holder = new ImplWithSmtpOutboundConfigUseTlsAccessorUnitTest()->withUseTls(true);
        $original = $holder->withUseTls( true);
        $same = $holder->withUseTls( true);
        $modified = $holder->withUseTls(false);

        // Act
        $withSame = $original->isUseTlsChanged( $same );
        $withDiferent = $original->isUseTlsChanged( $modified );

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithSmtpOutboundConfigUseTlsAccessorUnitTest
{
  use SmtpOutboundConfigUseTlsAccessor;
}
